var Roblox=Roblox||{};Roblox.Lang=Roblox.Lang||{};Roblox.Lang['Feature.AccountSettings']={"Action.Add":"Thêm","Action.AllowAccessContactsV3":"Truy Cập Vào Danh Bạ Của Thiết Bị","Action.Cancel":"Hủy Bỏ","Action.Delete":"Xóa","Action.Done":"Xong","Action.EditPaymentMethod":"Chỉnh sửa phương thức thanh toán","Action.Join":"Tham Gia","Action.Next":"Tiếp Theo","Action.Remove":"Loại Bỏ","Action.Report":"Báo cáo","Action.Save":"Lưu","Action.Show":"Hiển thị","Action.Subscribe":"Đăng Ký","Description.AccountEmailRevertEmail.From":"{escapeLiteralStart}Đặt Lại Email Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.AccountEmailRevertEmail.HtmlBody.V2":"Thân gửi {username},{lineBreak}{lineBreak}Chúng tôi nhận thấy bạn đã thay đổi địa chỉ email từ {oldEmailAddress} thành {newEmailAddress}. Nếu bạn là người thực hiện sự thay đổi này, vui lòng bỏ qua thông báo.{lineBreak}{lineBreak}Nếu bạn không thực hiện sự thay đổi này, hoặc vô tình thay đổi, nhấp vào liên kết để đổi lại email: {aTagWithHref}{revertAccountEmailLinkWithTicket}{hrefEnd}{revertAccountEmailLink}{aTagEnd}. Để tài khoản an toàn, bạn sẽ được yêu cầu thiết lập mật khẩu mới. {lineBreak}{lineBreak}Vui lòng không trả lời tin nhắn này. Nếu bạn có bất kỳ câu hỏi nào, vui lòng truy cập <a target=\"_blank\" href=\"{accountHelpLink}\">Trung Tâm Trợ Giúp</a>.","Description.AccountEmailRevertEmail.PlainBody.V2":"Thân gửi {username},{lineBreak}{lineBreak}Chúng tôi nhận thấy rằng bạn đã thay đổi địa chỉ email từ {oldEmailAddress} thành {newEmailAddress}. Nếu bạn đã thực hiện thay đổi này, xin hãy bỏ qua email này.{lineBreak}{lineBreak}Nếu bạn không thực hiện thay đổi này, xin hãy nhấp vào liên kết này để thay đổi lại email: {revertAccountEmailLink}. Để giữ cho tài khoản của bạn được an toàn, bạn sẽ được yêu cầu tạo mật khẩu mới.{lineBreak}{lineBreak}Vui lòng không phản hồi tin nhắn này. Nếu bạn có thắc mắc, vui lòng truy cập Trung Tâm Trợ Giúp ({accountHelpLink}).","Description.AccountEmailRevertEmail.Subject":"Đặ Lại Email Roblox","Description.AllowAccessContactsV2":"Bạn có thể quản lý quyền truy cập vào danh bạ của mình từ cài đặt quyền riêng tư của tài khoản trên thiết bị di động","Description.PasskeySkips2sv":"Mỗi khi đăng nhập bằng mã xác nhận, bạn sẽ bỏ qua phương thức Xác Thực 2 Bước đã chọn. Điều này là do mã xác nhận rất bảo mật và giúp xác thực rằng bạn đang sở hữu thiết bị của mình.","Description.Subscriptions.NoActive":"Bạn không có gói đăng ký đang hoạt động","Description.TranslationDisclaimer":"Bản dịch do Roblox cung cấp và có thể có lỗi. {linkStart}Tìm hiểu thêm.{linkEnd}","Description.TwoStepVerification":"Lớp Bảo Mật Tài Khoản Bổ Sung {lineBreaks}Ngoài mật khẩu của bạn, hãy thêm một lớp bảo vệ bổ sung cho tài khoản của bạn bằng Xác Thực 2 Bước cho đăng nhập, khôi phục tài khoản và giao dịch có giá trị cao. Lưu ý: bạn chỉ có thể bật mỗi lần một tùy chọn bên dưới.","Description.UsernameChangeEmail.From":"{escapeLiteralStart}Thay Đổi Tên Tài Khoản Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.UsernameChangeEmail.Message":"Yêu cầu đổi tên tài khoản đã được xử lý. Tên tài khoản đã được đổi từ {oldUsername} thành {newUsername}. Nếu bạn không yêu cầu đổi tên, hãy xem lại thông tin về trợ giúp tài khoản tại {startLink}Trung Tâm Trợ Giúp{endLink}. Vui lòng không trả lời trực tiếp email này vì thư trả lời sẽ không được nhận.","Description.UsernameChangeEmail.Subject":"Thay Đổi Tên Tài Khoản Roblox","Description.VerificationEmail.Body.Over13.V2":"{paragraphStart}Xin chào,{paragraphEnd}{paragraphStart}Cảm ơn bạn vì đã chọn bảo mật tài khoản Roblox của mình {emphasisStart}{username}{emphasisEnd} bằng cách cung cấp địa chỉ email.{paragraphEnd}{paragraphStart}Nếu bạn đã gửi yêu cầu này, vui lòng nhấp vào nút bên dưới để hoàn thành quá trình xác thực:{paragraphEnd}","Description.VerificationEmail.Body.Under13.V2":"{paragraphStart}Xin chào,{paragraphEnd}{paragraphStart}Con bạn đã tạo tài khoản {emphasisStart}{username}{emphasisEnd} trên Roblox, một nền tảng giải trí trực tuyến cho phép trẻ tưởng tượng, sáng tạo và chơi cùng nhau trong môi trường 3D nhập vai do người chơi sáng tạo.{paragraphEnd}{paragraphStart}Con bạn đã cung cấp cho chúng tôi tên tài khoản, ngày sinh và địa chỉ email phụ huynh. Vui lòng xác nhận địa chỉ email này là chính xác bằng cách {emphasisStart}nhấp vào nút bên dưới để hoàn thành quá trình xác minh{emphasisEnd}. Bất kể bạn có xác minh địa chỉ email phụ huynh hay không, trẻ vẫn có thể giữ lại tài khoản của mình và trò chuyện với người khác.{paragraphEnd}{paragraphStart}Bằng cách nhấp vào nút \"Tôi Đồng Ý, Xác Minh Email\", bạn cũng đồng ý rằng (a) Bạn và con bạn đồng ý với {aTagStartWithHref}{termsOfServiceLink}{hrefEnd}Điều Khoản{aTagEnd} Roblox, bao gồm cả trọng tài và (b) Bạn sẽ giám sát và chịu trách nhiệm hoàn toàn về việc con bạn sử dụng Roblox.{paragraphEnd}","Description.VerificationEmail.Body.Under13.V4":"{paragraphStart}Xin chào,{paragraphEnd}{paragraphStart}Email này nhằm thông báo về tài khoản của con bạn trên Roblox, {emphasisStart}{username}{emphasisEnd}, và tùy chọn để xác minh địa chỉ email của bạn để bật các tính năng an toàn và giám sát của phụ huynh cho tài khoản của con bạn. {paragraphEnd}{paragraphStart}Khi con bạn tạo tài khoản Roblox, chúng tôi đã thu thập những thông tin sau: tên tài khoản, mật khẩu, ngày sinh, và giới tính. Bạn hoặc con bạn đã thêm địa chỉ email phụ huynh vào tài khoản. Vui lòng xác thực tài khoản này bằng cách {emphasisStart}nhấp vào nút bên dưới:{emphasisEnd}{paragraphEnd}","Description.VerificationEmail.BodyLower.Over13.V2":"{paragraphStart}Cảm Ơn,{lineBreak}{emphasisStart}Đội Ngũ Roblox{emphasisEnd}{paragraphEnd}","Description.VerificationEmail.BodyLower.Under13.V2":"{paragraphStart}Bạn có thể cài đặt an toàn cho trẻ và giám sát của phụ huynh cho tài khoản Roblox của con mình tại {aTagStartWithHref}{accountSettingsLink}{hrefEnd}{accountSettingsLink}{aTagEnd}.{paragraphEnd}{paragraphStart}{emphasisStart}Hướng Dẫn Cho Phụ Huynh Về Roblox{emphasisEnd} {paragraphEnd}{paragraphStart}Chúng tôi khuyến khích bạn nên truy cập Hướng Dẫn Cho Phụ Huynh để giúp bản thân làm quen với nền tảng của chúng tôi và tìm các mẹo hữu ích nhằm tạo ra trải nghiệm tích cực cho con bạn trên Roblox: {aTagStartWithHref}{parentalPageLink}{hrefEnd}{parentalPageLink}{aTagEnd}{paragraphEnd}{paragraphStart}{emphasisStart}Quyền Riêng Tư{emphasisEnd}{paragraphEnd}{paragraphStart}Bạn có thể xóa tài khoản của con mình bất cứ lúc nào bằng cách liên hệ với dịch vụ khách hàng tại {aTagStartWithHref}{supportPageLink}{hrefEnd}{supportPageLink}{aTagEnd}. Email của bạn sẽ không được sử dụng cho bất kỳ mục đích nào khác, tiết lộ cho bên thứ ba hoặc kết hợp với bất kỳ thông tin cá nhân nào khác được thu thập từ con bạn. Để biết thêm thông tin, vui lòng xem lại chính sách quyền riêng tư của chúng tôi tại {aTagStartWithHref}{privacyPageLink}{hrefEnd}{privacyPageLink}{aTagEnd}.{paragraphEnd}{paragraphStart}Cảm Ơn,{lineBreak}{emphasisStart}Đội Ngũ Roblox{emphasisEnd}{paragraphEnd}","Description.VerificationEmail.BodyLower.Under13.V4":"{paragraphStart}Bằng cách xác minh tài khoản, bạn có quyền đặt lại mật khẩu của con bạn (khi cần thiết), được cập nhật những hoạt động của tài khoản của con bạn, và thiết lập cài đặt an toàn trẻ em và giám sát của phụ huynh cho tài khoản Roblox của trẻ tại https://www.roblox.com/my/account#!.{paragraphEnd}{paragraphStart}Nếu bạn không xác minh địa chỉ email, con bạn vẫn có thể sử dụng tài khoản, chơi trên Roblox và sử dụng hầu hết các tính năng, bao gồm cả bộ lọc trò chuyện.{paragraphEnd}{paragraphStart}Địa chỉ email của bạn sẽ không được sử dụng cho bất kỳ mục đích nào khác, tiết lộ cho bên thứ ba, hay liên kết với các thông tin cá nhân được thu thập từ con bạn. Ngoài email phụ huynh, chúng tôi không thu thập, sử dụng hay tiết lộ thông tin cá nhân của trẻ.{paragraphEnd}{paragraphStart}Để biết thêm thông tin về chính sách quyền riêng tư của chúng tôi, vui lòng truy cập https://www.roblox.com/info/privacy.{paragraphEnd}{paragraphStart}{emphasisStart}Hướng Dẫn Cho Phụ Huynh Về Roblox{emphasisEnd}{paragraphEnd}{paragraphStart} Roblox là sân chơi giải trí trực tuyến nơi trẻ được thỏa sức tưởng tượng, sáng tạo và giao lưu trong những thế giới 3D nhập vai được chính những người chơi sáng tạo nên.{paragraphEnd}{paragraphStart} Chúng tôi khuyên bạn nên xem Hướng Dẫn Cho Phụ Huynh của chúng tôi để làm quen với nền tảng này và có được những hướng dẫn để giúp con bạn có trải nghiệm tích cực trên Roblox: https://www.roblox.com/info/parents{paragraphEnd}{paragraphStart}{emphasisStart}Những Thông Tin Quan Trọng Khác{emphasisEnd}{paragraphEnd}{paragraphStart}Bạn có thể không cho con mình tham gia Robox, yêu cầu xóa tài khoản của con bạn,và/hoặc yêu cầu chúng tôi xóa địa chỉ email của bạn bất cứ lúc nào. Để thực hiện những yêu cầu này, vui lòng liên hệ với dịch vụ khách hàng tại https://www.roblox.com/support.{paragraphEnd}{paragraphStart}Bằng cách đồng ý cho con mình duy trì tài khoản Roblox, bạn đồng ý (a) bạn và con bạn đồng ý với {aTagStartWithHref}{termsOfServiceLink}{hrefEnd}Điều Khoản Của Roblox{aTagEnd}, bao gồm trọng tài và (b) bạn sẽ giám sát và hoàn toàn chịu trách nhiệm cho những hoạt động của trẻ trên Roblox.{paragraphEnd}{paragraphStart}Cảm Ơn,{paragraphEnd}{paragraphStart}Đội Ngũ Roblox{paragraphEnd}","Description.VerificationEmail.ButtonText.Over13.V2":"Xác Thực Email","Description.VerificationEmail.ButtonText.Under13.V2":"Tôi Đồng Ý, Xác Minh Email","Description.VerificationEmail.Footer.Over13.V2":"Vui lòng không trả lời email này. Bạn nhận được email này vì ai đó đã cố xác thực tài khoản Roblox bằng email của bạn. Nếu bạn không thực hiện yêu cầu này, vui lòng bỏ qua email này.","Description.VerificationEmail.Footer.Under13.V2":"Vui lòng không trả lời email này. Bạn nhận được email này vì ai đó đã cố xác thực tài khoản Roblox bằng email của bạn. Nếu bạn không thực hiện yêu cầu này, vui lòng bỏ qua email này.","Description.VerificationEmail.From.Over13":"{escapeLiteratStart}Xác Thực Email Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.VerificationEmail.From.Under13":"{escapeLiteratStart}Ủy Quyền Tài Khoản Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.VerificationEmail.Header.Over13.V2":"Xác Thực Email Roblox","Description.VerificationEmail.Header.Under13.V2":"Xác Thực Email Roblox","Description.VerificationEmail.HtmlBody.Over13":"Người chơi Roblox thân mến,{lineBreak}{lineBreak}Chúng tôi rất vui khi bạn đã chọn bảo mật tài khoản {username} bằng cách cung cấp địa chỉ email.{lineBreak}Khi xác thực địa chỉ email liên kết với tài khoản Roblox của bạn, độ bảo mật của tài khoản đã được tăng cường.{lineBreak}Vui lòng nhấn vào nút bên dưới để hoàn thành quá trình xác thực.{lineBreak}{lineBreak}{aTagStartWithHref}{verificationLink}{targetBlank}{buttonStart}Xác Thực Email{buttonEnd}{aTagEnd}","Description.VerificationEmail.HtmlBody.Under13":"Xin chào,{lineBreak}{lineBreak}Con của bạn vừa tạo một tài khoản {boldTagStart}{username}{boldTagEnd} trên Roblox, một nền tảng giải trí trực tuyến cho phép trẻ em có thể tưởng tượng, sáng tạo và chơi cùng nhau trong thế giới 3D nhập vai do người chơi tạo ra. Nền tảng của chúng tôi cũng cung cấp một công cụ phát triển miễn phí được gọi là “Roblox Studio” cho phép người dùng tạo ra bất cứ thứ gì họ tưởng tượng, từ những trải nghiệm xây dựng đơn giản bằng cách kéo và thả cho đến những trò nhiều người chơi phức tạp. Hàng triệu trẻ em đã tham gia Roblox để có những trải nghiệm như xây dựng một công viên giải trí đồ sộ, nhập vai thành một tay đua chuyên nghiệp, người mẫu trong một buổi diễn thời trang hoặc chỉ đơn giản là xây dựng một ngôi nhà trong mơ và vui chơi cùng bạn bè.{lineBreak}{lineBreak}Email này để thông báo rằng con của bạn đã cung cấp cho chúng tôi tên tài khoản, ngày sinh của trẻ và địa chỉ email phụ huynh. Địa chỉ email phụ huynh chỉ dùng cho mục đích quản lý tài khoản, đặt lại mật khẩu khi trẻ em quên mật khẩu và thông báo cho phụ huynh những thay đổi trong việc truy cập tài khoản của trẻ. Để xác thực địa chỉ email, vui lòng nhấp vào nút bên dưới: {lineBreak}{lineBreak}{aTagStartWithHref}{verificationLink}{hrefEnd}{buttonStart}Xác Thực Email{buttonEnd}{aTagEnd}{lineBreak}{lineBreak}{boldTagStart}Về Roblox{boldTagEnd}{lineBreak}{lineBreak}Roblox hướng tới việc xây dựng một môi trường vui vẻ và phù hợp với gia đình. Chúng tôi liên tục cải thiện những tính năng an toàn và hợp tác với các chuyên gia về an toàn kỹ thuật số để đảm bảo rằng mọi người chơi có một môi trường thoải mái để giải trí, trò chuyện và cùng nhau sáng tạo. Chúng tôi khuyến khích bạn nên xem qua Hướng Dẫn Cho Phụ Huynh để hiểu thêm về chúng tôi và có những mẹo bổ ích để giúp con bạn có nhiều trải nghiệm tích cực trên Roblox: {aTagStartWithHref}{parentalPageLink}{hrefEnd}{parentalPageLink}{aTagEnd}{lineBreak}{lineBreak}Roblox cũng cung cấp tính năng {boldTagStart}giám sát của phụ huynh{boldTagEnd}. Phụ huynh có thể tạo một mã PIN phụ huynh và thay đổi những cài đặt về trò chuyện và giao tiếp trong trò chơi của trẻ. Bạn có thể tìm những tính năng đó thông qua việc truy cập vào phần bảo mật và quyền riêng tư nằm trong cài đặt tài khoản khi đang đăng nhập vào tài khoản của con bạn.{lineBreak}{lineBreak}Để thêm mã PIN phụ huynh, vui lòng truy cập: {aTagStartWithHref}{accountSecurityLink}{hrefEnd}{accountSecurityLink}{aTagEnd}.{lineBreak}{lineBreak}Để thay đổi cài đặt trò chuyện, vui lòng truy cập: {aTagStartWithHref}{accountPrivacyLink}{hrefEnd}{accountPrivacyLink}{aTagEnd}.{lineBreak}{lineBreak}{boldTagStart}Quyền Riêng Tư{boldTagEnd}{lineBreak}{lineBreak}Bạn có thể xóa tài khoản của con bạn bằng cách liên hệ với dịch vụ khách hàng tại{aTagStartWithHref}{supportPageLink}{hrefEnd}{supportPageLink}{aTagEnd}. Địa chỉ email của bạn sẽ không được dùng cho mục đích nào khác, tiết lộ cho bên thứ ba hoặc kết hợp với những thông tin cá nhân khác được thu thập từ con của bạn. Để biết thêm chi tiết vui lòng xem lại chính sách quyền riêng tư tại {aTagStartWithHref}{privacyPageLink}{hrefEnd}{privacyPageLink}{aTagEnd}.{lineBreak}{lineBreak}{lineBreak}Xin cảm ơn,{lineBreak}{lineBreak}Đội Ngũ Roblox {lineBreak}{lineBreak} Không trả lời trực tiếp email này. {lineBreak}{lineBreak} {aTagStartWithHref}{robloxWebsiteLink}{hrefEnd}{robloxWebsiteLink}{aTagEnd} {lineBreak}{lineBreak} {aTagStartWithHref}{supportPageLink}{hrefEnd}{supportPageLink}{aTagEnd}","Description.VerificationEmail.Links.Over13.V2":"{aTagStartWithHref}{AccountSafetyArticleLink}{hrefEnd}An Toàn Tài Khoản{aTagEnd} | {aTagStartWithHref}{supportPageLink}{hrefEnd}Hỗ Trợ{aTagEnd}","Description.VerificationEmail.Links.Under13.V2":"{aTagStartWithHref}{parentalPageLink}{hrefEnd}Dành Cho Phụ Huynh{aTagEnd} | {aTagStartWithHref}{supportPageLink}{hrefEnd}Hỗ Trợ{aTagEnd}","Description.VerificationEmail.PlainBody.Over13":"Xin chào người chơi Roblox,{lineBreak}{lineBreak}Chúng tôi rất vui khi bạn đã chọn bảo mật tài khoản {username} bằng cách cung cấp địa chỉ email.{lineBreak}Khi xác thực địa chỉ email liên kết với tài khoản Roblox của bạn, độ bảo mật của tài khoản đã được tăng cường.{lineBreak}Vui lòng nhấp vào nút bên dưới để hoàn thành quá trình xác thực.{lineBreak}{verificationLink}.\n","Description.VerificationEmail.Subject.Over13":"Xác Thực Email Roblox","Description.VerificationEmail.Subject.Over13.V2":"Xác Thực Email Roblox: {username}","Description.VerificationEmail.Subject.Under13":"Ủy Quyền Tài Khoản Roblox","Description.VerificationEmail.Subject.Under13.V2":"Xác Minh Email Roblox: {username}","Description.VerificationEmail.Subject.Under13.V4":"Xác Minh Email Của Phụ Huynh Roblox: {username}","Heading.Billing":"Chi Trả","Heading.Dialog.DisableUpdateFriendsAboutMyActivity":"Tắt cập nhật hoạt động cho bạn bè","Heading.Dialog.ShareCurrentExperiencesWithFriends":"Đang chia sẻ trải nghiệm hiện tại của bạn với bạn bè","Heading.LoginMethods":"Phướng Thức Đăng Nhập","Heading.PageTitle":"Cài Đặt","Heading.PasskeyCreated":"Đã Tạo Mã Xác Nhận","Heading.PrivateServers":"Máy Chủ Riêng Tư","Heading.Subscriptions.Active":"Đang Hoạt Động ({activeNumber})","Label.CameraNotAvailable":"Camera không khả dụng trên một số thiết bị.","Label.CameraNotSupported":"Camera không khả dụng trên một số thiết bị. {linkStart}Tìm hiểu thêm{linkEnd}","Label.Cancel":"Hủy bỏ","Label.CreatedBy":"Bởi {creator}","Label.DropDown.No":"Không","Label.DropDown.Yes":"Có","Label.Email":"Địa Chỉ Email:","Label.Enable":"Bật","Label.Manage":"Quản Lý","Label.Passkey":"Mã Xác Nhận:","Label.Password":"Mật Khẩu:","Label.Phone":"Số Điện Thoại:","Label.Repeat":"Lặp lại","Label.ToolTip.UpdateFriendsAboutMyActivity":"Nếu bạn chọn \"Có\", bạn bè của bạn có thể được cập nhật về một số hoạt động gần đây của bạn trong các trải nghiệm.","Label.UpdateFriendsAboutMyActivity":"Cập nhật cho bạn bè về hoạt động của tôi?","Label.Username":"Tên Tài Khoản:","MessageInvalidEmail":"Email Không Hợp Lệ","MessagePinLockedError":"Mã PIN đã bị khóa.","MessageSettingsUpdateSuccess":"Cài đặt của bạn đã được cập nhật.","MessageUnknownError":"Đã xảy ra lỗi không xác định.","Response.Dialog.DisableUpdateFriendsAboutMyActivity":"Vì bạn không còn chia sẻ trải nghiệm hiện tại của mình với bạn bè, nên bạn bè của bạn cũng sẽ không được cập nhật về các hoạt động của bạn nữa.","Response.Dialog.ShareCurrentExperiencesWithFriends":"Vì bạn đã bật tính năng cập nhật hoạt động cho bạn bè, nên giờ đây bạn bè của bạn cũng có thể xem được những trò bạn đang chơi và cùng tham gia với bạn.","Response.VerificationError":"Đã xảy ra lỗi hệ thống trong quá trình xác thực."};Roblox.Lang['AccountSettingsResources']=Roblox.Lang['Feature.AccountSettings'];

