var Roblox=Roblox||{};Roblox.Lang=Roblox.Lang||{};Roblox.Lang['Feature.Parents']={"Action.ApproveRequest":"Chấp Thuận Yêu Cầu","Action.ContinueSetup":"Tiếp Tục Thiết Lập","Action.DoNotApprove":"Không Chấp Thuận","Action.EnterEmail":"Nhập Email","Action.Exit":"Thoát","Action.ExitSetup":"Thoát Thiết Lập","Action.GetStarted":"Bắt Đầu","Action.LinkAccount":"Liên Kết Tài Khoản","Action.RestartSession":"Khởi Động Lại Phiên","Action.ReviewRequest":"Kiểm Tra Yêu Cầu","Action.SendAnotherEmail":"Gửi Email Khác","Description.AllSet":"Yêu cầu này đã được trả lời","Description.AutoUnlink":"Khi trẻ đến tuổi trưởng thành, liên kết giữa tài khoản của bạn và tài khoản của trẻ sẽ tự động được gỡ. ","Description.CantLinkAccountCurrentChild":"Chúng tôi không thể liên kết tài khoản của bạn với tài khoản khác của trẻ. Để hoàn tất yêu cầu của trẻ, hãy nhập một địa chỉ email khác của bạn trên thiết bị của trẻ.","Description.ChargebackConsent":"Tài khoản của trẻ đã bị khoá do có giao dịch không được ủy quyền.{breakLine}Với vai trò phụ huynh, giờ bạn có quyền cho phép trẻ mở khoá tài khoản. ","Description.ChildHasMaxLinks":"Chúng tôi không thể liên kết tài khoản của bạn với tài khoản này của trẻ. Để hoàn tất yêu cầu của trẻ, hãy sử dụng tài khoản phụ huynh đã được liên kết rồi.","Description.DifferentEmail":"Email này đã được sử dụng bởi một tài khoản phụ huynh. Hãy mở lại email yêu cầu cấp quyền trong hộp thư đến và chọn Dùng Tài Khoản Hiện Có.","Description.DifferentEmailMidFlow":"Email này đã được sử dụng bởi một tài khoản phụ huynh. Để hoàn tất yêu cầu của trẻ, xin hãy nhập email khác của phụ huynh vào thiết bị của trẻ.","Description.EmailMismatch":"Địa chỉ email trong tệp không khớp với tài khoản này. Vui lòng đăng nhập bằng tài khoản khớp với email đã nhập trong thiết bị của trẻ.","Description.EmailSent":"Chúng tôi đã gửi email hướng dẫn các bước tiếp theo đến địa chỉ {parentEmail}","Description.EnterParentEmailV2":"Địa chỉ email này sẽ được liên kết với tài khoản Roblox của bạn. Để tìm hiểu thêm về cách chúng tôi sử dụng dữ liệu của bạn, vui lòng đọc {linkStart}Chính Sách Quyền Riêng Tư{linkEnd} của chúng tôi.","Description.ExistingParentButNotLinkedActionToRespond":"Để chấp thuận yêu cầu này, bạn sẽ cần liên kết tài khoản Roblox của mình.","Description.ExitEnterEmail":"Nếu bạn không nhập địa chỉ email, tài khoản của trẻ sẽ vẫn bị khoá. ","Description.GraduationApproachingEmailSubject":"Cập nhật quan trọng cho tài khoản phụ huynh trên Roblox","Description.GraduationApproachingEmailTopBodyText":"Tài khoản của bạn sẽ sớm ngắt liên kết với tài khoản của {childUsername}","Description.GraduationApproachingMessageBodySingular":"Tài khoản của bạn sẽ tự động dừng liên kết với tài khoản phụ huynh khi bạn đủ 18 tuổi, bắt đầu từ ngày {graduationDate}. Nghĩa là từ giờ bạn không cần xin phép phụ huynh để có quyền thực hiện một số hành động nhất định nữa.{lineBreak}{lineBreak}Nếu tuổi của bạn trong tài khoản không đúng, vui lòng vào mục {htmlBoldOpen}Cài Đặt > Thông Tin Tài Khoản{htmlBoldClose} để cập nhật lại. Còn nếu vẫn đúng thì bạn không cần phải làm gì thêm cả.{lineBreak}{lineBreak}Chúng tôi cũng đã gửi email cho phụ huynh của bạn để họ biết về thay đổi này.{lineBreak}{lineBreak}Với việc tiếp tục sử dụng Roblox sau khi đủ 18 tuổi, bạn đại diện cho chính mình đồng ý với {aTagWithHref}{termsOfUseLink}{hrefEnd}Điều Khoản Sử Dụng{htmlCloseAHref}, bao gồm điều khoản trọng tài và công nhận Chính Sách Quyền Riêng Tư của Roblox.{lineBreak}{lineBreak}{htmlBoldOpen}Những câu hỏi thường gặp{htmlBoldClose}{lineBreak}{lineBreak}{htmlBoldOpen}Tài khoản của phụ huynh tôi từ giờ sẽ như thế nào?{htmlBoldClose}{htmlListOpen}Phụ huynh của bạn vẫn có thể sử dụng Roblox như thường dù không liên kết với tài khoản của bạn.{htmlListClose}{htmlBoldOpen}Tôi có thể giữ liên kết với tài khoản của phụ huynh không?{htmlBoldClose}{htmlListOpen}Không. Bất kỳ người dùng Roblox nào khi tròn 18 tuổi đều không cần phải xin phép phụ huynh để thực hiện một số hành động nhất định.{htmlListClose}{htmlBoldOpen}{lineBreak}Nếu bạn có bất kỳ thắc mắc nào, vui lòng truy cập vào {aTagWithHref}{helpCenterLink}{hrefEnd}Trung Tâm Trợ Giúp{htmlCloseAHref} hoặc liên hệ với bộ phận {aTagWithHref}{supportPageLink}{hrefEnd}Chăm Sóc Khách Hàng{htmlCloseAHref} của chúng tôi.","Description.GraduationApproachingMessageSubjectPlural":"Tài khoản của bạn sẽ sớm ngắt liên kết với tài khoản của phụ huynh","Description.GraduationApproachingMessageSubjectSingular":"Tài khoản của bạn sẽ sớm ngắt liên kết với tài khoản của phụ huynh","Description.GraduationEmailFooter":"Vui lòng không trả lời tin nhắn này vì người gửi sẽ không nhận được tin nhắn của bạn.","Description.GraduationEmailFooterLinks":"{aTagWithHref}{learnMorePageLink}{hrefEnd}Tìm Hiểu Thêm{htmlCloseAHref} | {aTagWithHref}{accountSafetyPageLink}{hrefEnd}An Toàn Tài Khoản{htmlCloseAHref} | {aTagWithHref}{supportPageLink}{hrefEnd}Hỗ Trợ{htmlCloseAHref}","Description.GraduationEmailSubject":"Tài khoản của trẻ không còn liên kết với tài khoản Roblox của bạn","Description.GraduationEmailTopBodyText":"Tài khoản của bạn đã bị hủy liên kết với tài khoản của {childUsername}","Description.GraduationMessageBodyPluralV2":"Vì bạn đã đủ 18 tuổi nên tài khoản Roblox của bạn sẽ không còn liên kết với tài khoản của phụ huynh bạn nữa. Nghĩa là từ giờ bạn không cần xin phép phụ huynh để có quyền thực hiện một số hành động nhất định nữa.{lineBreak}{lineBreak}Với việc tiếp tục sử dụng Roblox sau khi đủ 18 tuổi, bạn đại diện cho chính mình đồng ý với {aTagWithHref}{termsOfUseLink}{hrefEnd}Điều Khoản Sử Dụng{htmlCloseAHref}, bao gồm điều khoản trọng tài và công nhận Chính Sách Quyền Riêng Tư của Roblox.{lineBreak}{lineBreak}Nếu bạn có bất kỳ thắc mắc nào, vui lòng liên hệ với bộ phận {aTagWithHref}{supportPageLink}{hrefEnd}Hỗ Trợ Của Roblox{htmlCloseAHref}.","Description.GraduationMessageBodySingular":"Vì bạn đã đủ 18 tuổi nên tài khoản Roblox của bạn sẽ không còn liên kết với tài khoản của phụ huynh bạn nữa. Nghĩa là từ giờ bạn không cần xin phép phụ huynh để có quyền thực hiện một số hành động nhất định nữa.{lineBreak}{lineBreak}Với việc tiếp tục sử dụng Roblox sau khi đủ 18 tuổi, bạn đại diện cho chính mình đồng ý với {aTagWithHref}{termsOfUseLink}{hrefEnd}Điều Khoản Sử Dụng{htmlCloseAHref}, bao gồm điều khoản trọng tài và công nhận Chính Sách Quyền Riêng Tư Của Roblox.{lineBreak}{lineBreak}Nếu bạn có bất kỳ thắc mắc nào, vui lòng truy cập vào {aTagWithHref}{helpCenterLink}{hrefEnd}Trung Tâm Trợ Giúp{htmlCloseAHref} hoặc liên hệ với bộ phận {aTagWithHref}{supportPageLink}{hrefEnd}Chăm Sóc Khách Hàng{htmlCloseAHref} của chúng tôi.","Description.GraduationMessageBodySingularV2":"Vì bạn đã đủ 18 tuổi nên tài khoản Roblox của bạn sẽ không còn liên kết với tài khoản của phụ huynh bạn nữa. Nghĩa là từ giờ bạn không cần xin phép phụ huynh để có quyền thực hiện một số hành động nhất định nữa.{lineBreak}{lineBreak}Với việc tiếp tục sử dụng Roblox sau khi đủ 18 tuổi, bạn đại diện cho chính mình đồng ý với {aTagWithHref}{termsOfUseLink}{hrefEnd}Điều Khoản Sử Dụng{htmlCloseAHref}, bao gồm điều khoản trọng tài và công nhận Chính Sách Quyền Riêng Tư Của Roblox.{lineBreak}{lineBreak}Nếu bạn có bất kỳ thắc mắc nào, vui lòng liên hệ với bộ phận {aTagWithHref}{supportPageLink}{hrefEnd}Hỗ Trợ Của Roblox{htmlCloseAHref}.","Description.GraduationMessageSubjectPlural":"Tài khoản của bạn sẽ hủy liên kết với tài khoản của phụ huynh trong hôm nay","Description.GraduationMessageSubjectSingular":"Tài khoản của bạn sẽ hủy liên kết với tài khoản của phụ huynh trong hôm nay","Description.GuardianRequirement":"Bạn phải là phụ huynh hoặc người giám hộ hợp pháp để có quyền quản lý tài khoản của trẻ","Description.IDVRequired":"Tài khoản Roblox của bạn vẫn chưa có đặc quyền phụ huynh. Để hoàn tất yêu cầu của trẻ sau này, hãy nhấn vào “Dùng tài khoản có sẵn” trong hộp thư đến của email của bạn.","Description.LinToChild":"Sau khi liên kết, bạn có thể phê duyệt một số hành động nhất định mà trẻ có thể thực hiện","Description.LogOut":"Để liên kết một tài khoản hiện có, hãy đăng xuất khỏi phiên hiện tại và đăng nhập lại.","Description.LogOutSignup":"Để tạo tài khoản mới, trước tiên bạn cần đăng xuất phiên hiện tại.","Description.MoreAboutUpdateBirthdate":"Trẻ cần được phụ huynh hoặc người giám hộ cho phép cập nhật ngày sinh trên tài khoản Roblox.{lineBreak}{lineBreak}Chúng tôi rất coi trọng quyền riêng tư của trẻ. Người khác sẽ không nhìn thấy ngày sinh của trẻ. Thông tin này giúp chúng tôi biết nên hiển thị nội dung gì cho trẻ trên Roblox.","Description.NewParentActionToRespond":"Để chấp thuận yêu cầu này, bạn cần có tài khoản Roblox có đặc quyền của phụ huynh.","Description.ParentAccountSetupEmailBottomBodyTextSavePaymentMethods":"{htmlBoldOpen}Thông tin bổ sung về yêu cầu của trẻ{htmlBoldClose}{lineBreak}{lineBreak}{htmlItalicsOpen}Có cần sự cho phép của cha mẹ cho mỗi lượt mua không?{htmlItalicsClose}{lineBreak}{lineBreak}Chúng tôi không yêu cầu phải có sự cho phép của cha mẹ đối với các giao dịch mua riêng lẻ, tuy nhiên, bạn sẽ nhận được biên lai sau mỗi lần hoàn tất mua sắm. Nếu trẻ dưới 13 tuổi, bạn có thể giúp quản lý tổng mức chi tiêu hàng tháng của trẻ bằng cách bật chức năng Hạn Chế Chi Tiêu Hàng Tháng trong phần Cài đặt tài khoản của trẻ.{lineBreak}{lineBreak}{htmlItalicsOpen}Làm thế nào để xóa phương thức thanh toán khỏi tài khoản của trẻ?{htmlItalicsClose}{lineBreak}{lineBreak}Để xóa phương thức thanh toán đã lưu, hãy truy cập vào trang Phương thức thanh toán trong phần cài đặt Roblox của trẻ. Việc xóa tất cả các phương thức thanh toán đã lưu sẽ rút lại quyền lưu phương thức thanh toán mới khỏi tài khoản của trẻ.{lineBreak}{lineBreak}{htmlItalicsOpen}Chuyện gì sẽ xảy ra nếu tôi không chấp thuận yêu cầu này?{htmlItalicsClose}{lineBreak}{lineBreak}Trẻ sẽ không lưu lại phương thức thanh toán vào tài khoản Roblox của mình, và sẽ không thể mua gói đăng ký trong các trải nghiệm. Tuy nhiên, trẻ vẫn có thể thực hiện giao dịch mua sắm (không cần có sự cho phép của cha mẹ) bằng cách nhập thông tin thanh toán hoặc xác thực thông tin thanh toán trên App Store khi thanh toán.{lineBreak}{lineBreak}{htmlBoldOpen}Giới thiệu về đặc quyền của cha mẹ trên Roblox{htmlBoldClose}{lineBreak}{lineBreak}Nói chung, chúng tôi không yêu cầu trẻ em trên Roblox phải liên kết với một tài khoản có đặc quyền của cha mẹ. Tuy nhiên, trong một số trường hợp nhất định, trẻ em có thể cần tới sự cho phép của cha mẹ, ví dụ như mở khóa tài khoản hoặc lưu phương thức thanh toán.{lineBreak}{lineBreak}Việc tạo tài khoản có đặc quyền của cha mẹ chỉ mất vài phút. Bạn sẽ được yêu cầu nhập ngày sinh của mình, xác minh tuổi bằng căn cước công dân do Chính phủ cấp, rồi liên kết tài khoản này với tài khoản Roblox của trẻ. Sau đó, bạn sẽ có thể phê duyệt một số hành động nhất định cho trẻ trên Roblox. Bạn cũng có thể khám phá Roblox bằng nhân vật đại diện của mình hoặc cùng với trẻ.{lineBreak}{lineBreak}Nếu đã có tài khoản Roblox riêng, bạn có thể liên kết tài khoản đó với tài khoản của trẻ và bổ sung các đặc quyền của cha mẹ.","Description.ParentAccountSetupEmailBottomBodyTextV2":"{htmlBoldOpen}Tài khoản Roblox với đặc quyền phụ huynh là gì?{htmlBoldClose}{lineBreak}{lineBreak}Tài khoản với đặc quyền phụ huynh là tài khoản mà bạn có quyền cho phép trẻ thực hiện một số hành động trong Roblox. Ngoài ra, bạn cũng có thể tự mình dùng avatar hoặc cùng trẻ khám phá Roblox.{lineBreak}{lineBreak}{htmlBoldOpen}Nếu tôi đã có tài khoản Roblox rồi thì sao?{htmlBoldClose}{lineBreak}{lineBreak}Nếu đã có tài khoản Roblox rồi, bạn có thể liên kết tài khoản đó với tài khoản của trẻ và thêm đặc quyền phụ huynh.{lineBreak}{lineBreak}{htmlBoldOpen}Tại sao tôi cần tài khoản với đặc quyền phụ huynh?{htmlBoldClose}{lineBreak}{lineBreak}Thường thì chúng tôi không yêu cầu người chơi tuổi vị thành niên trên Roblox liên kết với tài khoản có đặc quyền phụ huynh. Tuy nhiên, trong một số trường hợp nhất định, trẻ có thể cần sự cho phép của phụ huynh, chẳng hạn như khi cần mở khoá tài khoản.{lineBreak}{lineBreak}{htmlBoldOpen}Vậy tôi cần phải làm gì?{htmlBoldClose}{lineBreak}{lineBreak}Bạn cần tạo một tài khoản với đặc quyền phụ huynh, việc này chỉ mất vài phút. Bạn sẽ phải nhập sinh nhật, dùng Căn Cước để xác thực tuổi và liên kết với tài khoản Roblox của trẻ.{lineBreak}{lineBreak}Nếu tạo tài khoản mới thông qua quá trình này, hiện tại bạn chỉ có thể đăng nhập vào tài khoản này trên trình duyệt.","Description.ParentAccountSetupEmailFooterText":"Vui lòng không trả lời tin nhắn này vì người gửi sẽ không nhận được tin nhắn của bạn.","Description.ParentAccountSetupEmailLinksV2":"{aTagWithHref}{learnMorePageLink}{hrefEnd}Tìm Hiểu Thêm{htmlCloseAHref} | {aTagWithHref}{accountSafetyPageLink}{hrefEnd}An Toàn Tài Khoản{htmlCloseAHref} | {aTagWithHref}{supportPageLink}{hrefEnd}Hỗ \nTrợ{htmlCloseAHref}","Description.ParentAccountSetupEmailSubject":"Trẻ cần sự cho phép của bạn trên Roblox","Description.ParentAccountSetupEmailTopBodyText":"Con của bạn, tên tài khoản là {childUsername}, cần bạn cho phép mở khoá tài khoản Roblox. Để cho phép trẻ làm điều đó, bạn cần có một tài khoản Roblox với đặc quyền phụ huynh.","Description.ParentAccountSetupEmailTopBodyTextSavePaymentMethods":"Con của bạn, {childUsername}, muốn lưu phương thức thanh toán vào tài khoản Roblox của mình. Phương thức thanh toán đã lưu có thể được dùng cho tất cả các giao dịch mua sắm trong tương lai trên Roblox.{lineBreak}{lineBreak}Để phê duyệt yêu cầu của trẻ, trước tiên, bạn cần có tài khoản Roblox có đặc quyền của cha mẹ.","Description.ParentPermissionV2":"Một số hành động trên Roblox cần sự cho phép của phụ huynh hoặc người giám hộ.{lineBreak}Để giúp trẻ thực hiện hành động đó, bạn cần có một tài khoản Roblox với đặc quyền phụ huynh. Bạn sẽ phải cung cấp email, xác thực tuổi và liên kết với tài khoản của trẻ.","Description.ProcessingVerification":"Chúng tôi đang xử lý quá trình xác thực ID cho bạn. Vui lòng không đóng cửa sổ này cho đến khi quá trình xác thực hoàn tất.","Description.RequestExpired":"Mở Roblox trên thiết bị của trẻ và nhập lại email của bạn để bắt đầu lại","Description.RestartSession":"Để khởi động lại quy trình và hoàn tất yêu cầu của trẻ, hãy nhập lại email của bạn trên thiết bị của trẻ. ","Description.SaveCreditCardConsent":"Con của bạn cần sự đồng ý của bạn để lưu các phương thức thanh toán vào tài khoản. Một phương thức thanh toán đã lưu có thể được sử dụng để thực hiện các giao dịch mua sắm trên Roblox, bao gồm mua gói đăng ký. {breakLine}Là một phụ huynh, bạn sẽ nhận được thông báo qua email cho mỗi giao dịch mua sắm. Bạn cũng có thể xóa các phương thức thanh toán bất kỳ lúc nào. {linkStart}Tìm hiểu thêm{linkEnd}\n","Description.UpdateBirthdateEmailSubject":"Xem lại yêu cầu của trẻ để cập nhật ngày sinh nhật của trẻ","Description.UpdateBirthdateRequest":"Con em của bạn, {childUsername}, muốn cập nhật ngày sinh.","Description.UserAgreementExplanation":"Bằng cách chọn “Đồng Ý”, bạn nhận mình là phụ huynh hoặc người giám hộ hợp phát của trẻ vị thành niên này và đồng ý nhận thông tin liên quan đến tài khoản của trẻ. Bạn cũng thay mặt trẻ đồng ý với {tosLinkStart}Điều Khoản Sử Dụng{tosLinkEnd}, bao gồm điều khoản trọng tài và công nhận {PPLinkStart}Chính Sách Quyền Riêng Tư{PPLinkEnd}.","Description.UserDeleted":"Tài khoản này của trẻ không còn tồn tại.","Description.VerifyEmail":"Trước tiên, vào Cài Đặt > Thông Tin Tài Khoản để xác thực địa chỉ email Roblox của bạn. Sau đó, quay lại email chứa liên kết và phê duyệt yêu cầu của trẻ.","Description.WaitingParentPermissionV2":"Hãy kiểm tra email của bạn để tiến hành mở khoá tài khoản của trẻ.{lineBreak}Sau khi cấp quyền xong, vui lòng làm mới màn hình này để quay lại tài khoản Roblox của trẻ.","Heading.ApproveChildRequest":"Chấp Thuận Yêu Cầu Của Trẻ","Label.Email":"email","Label.ExistingParentButNotLinkedSigninButton":"Liên Kết Tài Khoản","Label.LinkedParentSigninButton":"Xem lại","Label.ParentAccountSetupEmailSigninButton":"Dùng Tài Khoản Có Sẵn","Label.ParentAccountSetupEmailSignupButton":"Tạo Tài Khoản","Label.PleaseDoNotClose":"Vui lòng không đóng cửa sổ này cho đến khi quá trình xác thực hoàn tất.","Message.ChildCanUnlock":"Trẻ giờ có thể mở khoá tài khoản trên thiết bị của mình ","Message.EmailIneligible":"Email này không đủ điều kiện. Hãy sử dụng một email khác để xin cấp phép trên Roblox.","Message.ExistAccountWithEmail":"Phụ huynh của bạn đã có tài khoản phê duyệt yêu cầu. Thay vào đó, hãy nhập email của phụ huynh bạn.","Message.ExitChargebackConsent":"Trẻ sẽ không thể sử dụng Roblox khi tài khoản đang bị khoá","Message.ExitMessage":"Tiếp tục hoàn thành yêu cầu của trẻ","Message.ExitSavePaymentMethodsConsent":"Trẻ sẽ không thể lưu phương thức thanh toán","Message.InvalidEmail":"Địa chỉ email không hợp lệ","Message.LinkExitWarning":"Bạn sẽ không thể truy cập tính năng giám sát của cha mẹ và thông tin chi tiết về trẻ nếu không liên kết tài khoản","Message.SaveCreditCardSuccess":"Khi con của bạn mua một gói đăng ký trên Roblox, bạn có thể lưu thủ công một phương thức thanh toán vào tài khoản Roblox của trẻ để sử dụng trong tương lai. ","Message.SomethingWentWrong":"Đã xảy ra sự cố","Message.TooManyAttempts":"Bạn đã thử quá nhiều lần. Vui lòng thử lại sau.","Titile.CantLinkAccount":"Không Thể Liên Kết Tài Khoản","Title.AddEmail":"Thêm Email Của Bạn","Title.AllSet":"Bạn đã hoàn thành yêu cầu","Title.AreYouSure":"Bạn Chắc Chứ?","Title.CantLinkAccount":"Không Thể Liên Kết Tài Khoản","Title.DifferentEmail":"Email Đã Được Sử Dụng","Title.EmailMismatch":"Email Không Khớp","Title.EnterParentEmail":"Nhập Email Của Phụ Huynh","Title.ExitMessage":"Tiếp Tục Hoặc Thoát","Title.IDVRequired":"Yêu Cầu Xác Thực ID","Title.IneligibleAccount":"Tài Khoản Không Đủ Điều Kiện","Title.LinkToChild":"Liên Kết Với Tài Khoản Của Trẻ","Title.LogOut":"Đăng Xuất","Title.NoAccountCreation":"Không Tạo Được Tài Khoản","Title.ParentPermission":"Cần Phụ Huynh Cho Phép","Title.ProcessingVerification":"Đang Xử Lý Yêu Cầu Xác Thực","Title.RequestApproved":"Yêu Cầu Đã Được Chấp Thuận","Title.RequestExpired":"Yêu cầu đã hết hạn","Title.SignInError":"Lỗi Đăng Nhập","Title.SomethingWentWrong":"Đã Xảy Ra Sự Cố","Title.Thanks":"Xin cảm ơn!","Title.UserDeleted":"Không Thể Cấp Quyền","Title.VerifyEmail":"Xác Thực Email Của Bạn","Title.WaitingParentPermission":"Đang Chờ Phụ Huynh Cho Phép"};Roblox.Lang['ParentsResources']=Roblox.Lang['Feature.Parents'];

